<script setup>
import { computed,onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue';import { storeToRefs } from 'pinia';import { useNpwStore } from '@/stores/npw'
const store=useNpwStore();const {filters,equipmentOptions,ppidOptions,allRows}=storeToRefs(store);const root=ref();const open=ref('');const draft=reactive({...filters.value,eqpids:[...filters.value.eqpids],chids:[...filters.value.chids],ppids:[...filters.value.ppids]});const sync=v=>Object.assign(draft,{...v,eqpids:[...v.eqpids],chids:[...v.chids],ppids:[...v.ppids]});watch(()=>filters.value,sync,{deep:true});const chamberOptions=computed(()=>[...new Set(allRows.value.filter(r=>!draft.eqpids.length||draft.eqpids.includes(r.eqpid)).map(r=>r.chid))].sort());const fields=computed(()=>[{key:'eqpids',label:'EQP',options:equipmentOptions.value},{key:'chids',label:'CHID',options:chamberOptions.value},{key:'ppids',label:'PPID',options:ppidOptions.value}]);const summary=k=>draft[k].length?draft[k].length===1?draft[k][0]:`${draft[k].length}개 선택`:'선택 없음';const toggle=k=>open.value=open.value===k?'':k;const allSelected=field=>field.options.length>0&&field.options.every(option=>draft[field.key].includes(option));const toggleAll=field=>{draft[field.key]=allSelected(field)?[]:[...field.options]};function apply(){store.applyFilters(draft);open.value=''}function reset(){draft.eqpids=[];draft.chids=[];draft.ppids=[];store.applyFilters(draft);open.value=''}function outside(e){if(!root.value?.contains(e.target))open.value=''}onMounted(()=>document.addEventListener('click',outside));onBeforeUnmount(()=>document.removeEventListener('click',outside))
</script>
<template><section ref="root" class="filterbar"><label class="date">DATE RANGE<div><input v-model="draft.startDate" type="date"><span>~</span><input v-model="draft.endDate" type="date"></div></label><div v-for="field in fields" :key="field.key" class="multi"><b>{{field.label}}</b><button class="trigger" @click="toggle(field.key)"><span>{{summary(field.key)}}</span><i>⌄</i></button><div v-if="open===field.key" class="menu"><label class="select-all"><input type="checkbox" :checked="allSelected(field)" @change="toggleAll(field)"><span>모두 선택</span></label><label v-for="option in field.options" :key="option"><input v-model="draft[field.key]" type="checkbox" :value="option"><span>{{option}}</span></label><p v-if="!field.options.length">선택 가능한 항목 없음</p></div></div><span class="spacer"></span><button class="reset" @click="reset">⚲　필터 초기화</button><button class="apply" @click="apply">Apply Filters</button></section></template>
<style scoped>.filterbar{display:grid;grid-template-columns:300px 145px 130px 230px minmax(20px,1fr) 118px 118px;align-items:end;gap:16px;padding:18px 20px;background:#fff;border:1px solid #dfe5eb;border-radius:12px;box-shadow:0 5px 18px rgba(35,55,75,.07)}.filterbar .date{display:grid;gap:6px;color:#506579;font-size:10px;font-weight:800;letter-spacing:.04em}.date>div{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:5px}.date input{width:100%;min-width:0;height:38px;padding:0 9px;color:#263a4d;background:#f8fafc;border:1px solid #d7e0e8;border-radius:8px;font-size:11px;font-weight:600}.multi{position:relative;display:grid;gap:6px}.multi>b{color:#506579;font-size:10px;letter-spacing:.04em}.trigger{display:flex!important;justify-content:space-between;align-items:center;width:100%!important;padding:0 11px!important;text-align:left}.trigger i{color:#7357c8;font-style:normal}.menu{position:absolute;z-index:30;top:60px;left:0;width:max(100%,145px);max-height:190px;padding:6px;background:#fff;border:1px solid #d9d1ef;border-radius:8px;box-shadow:0 10px 24px rgba(65,45,115,.16);overflow-y:auto}.menu label{display:flex;align-items:center;gap:8px;padding:7px 8px;border-radius:6px;color:#354b5f;font-size:11px;cursor:pointer}.menu label:hover{background:#f3effc}.menu .select-all{margin-bottom:3px;padding-bottom:8px;border-bottom:1px solid #e7e1f3;border-radius:0;color:#6d28d9;font-weight:800}.menu input{width:14px;height:14px;accent-color:#7c3aed}.menu p{margin:5px;color:#8290a2;font-size:10px}.filterbar>button,.trigger{height:38px;background:#f8fafc;border:1px solid #d7e0e8;border-radius:8px;color:#43586b;font-size:11px;font-weight:700;white-space:nowrap;cursor:pointer}.filterbar>.reset,.filterbar>.apply{width:118px;padding:0 16px;justify-self:end}.filterbar>.reset:hover{color:#6d28d9;border-color:#b9a7e5}.filterbar>.apply{color:#fff;background:#7357c8;border-color:#7357c8;box-shadow:0 4px 10px rgba(90,64,160,.18)}@media(max-width:1200px){.filterbar{grid-template-columns:2fr repeat(3,1fr)}.spacer{display:none}.filterbar>.reset,.filterbar>.apply{justify-self:start}}@media(max-width:800px){.filterbar{grid-template-columns:1fr 1fr}.date{grid-column:1/-1}}</style>
